create extension if not exists pgcrypto;

create table if not exists public.products (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null default '', price integer not null default 0 check (price >= 0), compare_at_price integer check (compare_at_price is null or compare_at_price >= 0), stock integer not null default 0 check (stock >= 0), colors text[] not null default '{}', sizes text[] not null default '{}', image_urls text[] not null default '{}', badge text, is_featured boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.delivery_rates (id bigint generated by default as identity primary key, wilaya text not null unique, home_price integer not null default 0 check (home_price >= 0), stop_desk_price integer not null default 0 check (stop_desk_price >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_number text unique, customer_name text not null, phone text not null, email text, wilaya text not null, commune text not null, address text, delivery_method text not null check (delivery_method in ('home','stop_desk')), delivery_price integer not null default 0 check (delivery_price >= 0), subtotal integer not null default 0 check (subtotal >= 0), total integer not null default 0 check (total >= 0), status text not null default 'new' check (status in ('new','confirmed','preparing','shipped','delivered','cancelled')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name text not null, quantity integer not null check (quantity > 0), unit_price integer not null check (unit_price >= 0), color text, size text, created_at timestamptz not null default now());
create table if not exists public.store_settings (id boolean primary key default true check (id = true), brand_name text not null default 'ZANK STUDIO', phone text not null default '0798460604', instagram text not null default 'zankstudio', locations text not null default 'Algiers / Oran', announcement_text text not null default '', announcement_enabled boolean not null default false, updated_at timestamptz not null default now());
insert into public.store_settings (id) values (true) on conflict (id) do nothing;

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists products_updated_at on public.products; create trigger products_updated_at before update on public.products for each row execute function public.set_updated_at();
drop trigger if exists delivery_rates_updated_at on public.delivery_rates; create trigger delivery_rates_updated_at before update on public.delivery_rates for each row execute function public.set_updated_at();
drop trigger if exists orders_updated_at on public.orders; create trigger orders_updated_at before update on public.orders for each row execute function public.set_updated_at();
drop trigger if exists store_settings_updated_at on public.store_settings; create trigger store_settings_updated_at before update on public.store_settings for each row execute function public.set_updated_at();
create or replace function public.set_order_number() returns trigger language plpgsql as $$ begin if new.order_number is null then new.order_number := 'ZK-' || to_char(new.created_at, 'YYMMDD') || '-' || upper(substr(replace(new.id::text,'-',''),1,6)); end if; return new; end; $$;
drop trigger if exists orders_order_number on public.orders; create trigger orders_order_number before insert on public.orders for each row execute function public.set_order_number();

alter table public.products enable row level security; alter table public.delivery_rates enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.store_settings enable row level security;
drop policy if exists products_public_read on public.products; create policy products_public_read on public.products for select using (is_active = true or auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists products_admin_write on public.products; create policy products_admin_write on public.products for all using (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com') with check (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists delivery_public_read on public.delivery_rates; create policy delivery_public_read on public.delivery_rates for select using (true);
drop policy if exists delivery_admin_write on public.delivery_rates; create policy delivery_admin_write on public.delivery_rates for all using (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com') with check (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists orders_public_insert on public.orders; create policy orders_public_insert on public.orders for insert with check (true);
drop policy if exists orders_admin_read on public.orders; create policy orders_admin_read on public.orders for select using (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists orders_admin_update on public.orders; create policy orders_admin_update on public.orders for update using (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com') with check (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists order_items_public_insert on public.order_items; create policy order_items_public_insert on public.order_items for insert with check (true);
drop policy if exists order_items_admin_read on public.order_items; create policy order_items_admin_read on public.order_items for select using (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists settings_public_read on public.store_settings; create policy settings_public_read on public.store_settings for select using (true);
drop policy if exists settings_admin_write on public.store_settings; create policy settings_admin_write on public.store_settings for all using (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com') with check (auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');

insert into storage.buckets (id, name, public) values ('product-images','product-images',true) on conflict (id) do update set public = true;
drop policy if exists product_images_public_read on storage.objects; create policy product_images_public_read on storage.objects for select using (bucket_id = 'product-images');
drop policy if exists product_images_admin_insert on storage.objects; create policy product_images_admin_insert on storage.objects for insert with check (bucket_id = 'product-images' and auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists product_images_admin_update on storage.objects; create policy product_images_admin_update on storage.objects for update using (bucket_id = 'product-images' and auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');
drop policy if exists product_images_admin_delete on storage.objects; create policy product_images_admin_delete on storage.objects for delete using (bucket_id = 'product-images' and auth.jwt() ->> 'email' = 'a.g.b.morphzy@gmail.com');

